    'faq' => [
        ['q' => "Un cabinet médical a-t-il besoin d'une autorisation pour informatiser ses dossiers au Bénin ?", 'r' => "Le code du numérique soumet les traitements de données de santé à l'autorisation préalable de l'APDP (articles 394 et 407). Une structure qui prépare un dossier informatisé monte donc la demande avant la mise en service. À confirmer auprès de l'autorité, car ses formulaires peuvent évoluer."],
        ['q' => "Peut-on héberger les dossiers patients chez un hébergeur situé à l'étranger ?", 'r' => "Au Bénin, l'article 391 ne permet un transfert vers un État tiers que si l'APDP constate que cet État assure un niveau de protection équivalent. En France, l'hébergeur de données de santé numériques doit détenir un certificat de conformité (article L.1111-8 du code de la santé publique). Le lieu des sauvegardes se vérifie dans le contrat."],
        ['q' => "Un assistant WhatsApp peut-il répondre aux questions médicales des patients ?", 'r' => "Non. Il se limite aux horaires, aux pièces à apporter et aux informations pratiques, et il oriente vers l'accueil ou vers un numéro d'urgence dès qu'un symptôme est décrit. La politique WhatsApp Business restreint aussi l'envoi d'informations de santé."],
        ['q' => "L'IA peut-elle rédiger un compte rendu de consultation ?", 'r' => "Elle peut proposer un brouillon à partir de notes saisies dans le logiciel de la structure. Le médecin relit tout et signe : la transcription reste un brouillon tant qu'il ne l'a pas validée. Aucune donnée de patient ne se colle dans un assistant public."],
        ['q' => "Odoo convient-il à une clinique ?", 'r' => "Pour la facturation des actes, la caisse, les achats, le stock de consommables et la comptabilité, oui. Odoo n'inclut pas de dossier clinique en standard ; le dépôt communautaire OCA vertical-medical existe, avec une branche 19.0 affichée le 7 octobre 2026, et se vérifie avant usage."],
        ['q' => "Dolibarr et DoliMed suffisent-ils pour un petit cabinet ?", 'r' => "Ils peuvent convenir à un petit cabinet qui utilise déjà Dolibarr. DoliMed existe en module pour Dolibarr et en version autonome : la compatibilité avec la version de Dolibarr retenue se contrôle avant d'installer quoi que ce soit."],
        ['q' => "Comment encaisser les consultations par mobile money ?", 'r' => "Avec un agrégateur de paiement et un rapprochement de chaque règlement avec sa facture. Le choix se fait avec le comparatif des agrégateurs publié sur ce site, et la structure ne conserve jamais de numéro de carte."],
        ['q' => "La facture normalisée s'applique-t-elle à une clinique béninoise ?", 'r' => "Elle vise les entreprises assujetties à la TVA, selon le site du gouvernement. La situation d'une structure donnée se confirme avec son cabinet comptable ou la direction générale des impôts avant de choisir le logiciel de facturation."],
        ['q' => "La téléconsultation est-elle possible sans logiciel spécialisé ?", 'r' => "Techniquement oui, mais le circuit complet demande un créneau, un paiement, un lien sécurisé et un compte rendu. Le cadre de la télémédecine se vérifie auprès de l'ordre et du ministère du pays d'exercice avant d'ouvrir le service."],
        ['q' => "Combien de temps dure un projet de numérisation pour un cabinet ?", 'r' => "La durée dépend du projet : une prise de rendez-vous en ligne se met en place plus vite qu'un dossier patient avec reprise des données. Le calendrier se fixe après le diagnostic, par paliers, avec une réponse sous 24 heures au premier message."],
        ['q' => "Combien coûte la numérisation d'une clinique ?", 'r' => "Un site vitrine démarre à 300 000 FCFA, soit environ 457 €. Le dossier patient, la facturation, la caisse et l'IA se chiffrent sur devis, après un premier échange. Le prix dépend du nombre de praticiens, de l'hébergement et de l'état des données."],
        ['q' => "Richard a-t-il déjà formé des médecins ?", 'r' => "Oui, Richard a déjà formé des médecins et des équipes de cliniques. Il propose de placer les séances hors des heures de consultation et de les faire sur des patients fictifs, jamais sur des dossiers réels."],
    ],

